/* eslint-disable array-element-newline */

'use strict';

// MODULES //

var dtypes = require( '@stdlib/ndarray-dtypes' );
var gcusome = require( '@stdlib/blas-ext-base-ndarray-gcusome' );
var dcusome = require( '@stdlib/blas-ext-base-ndarray-dcusome' );
var scusome = require( '@stdlib/blas-ext-base-ndarray-scusome' );
var factory = require( '@stdlib/ndarray-base-unary-strided1d-dispatch-factory' );


// VARIABLES //

var idtypes0 = dtypes( 'all' ); // input ndarray
var idtypes1 = dtypes( 'integer_index_and_generic' ); // minimum number of truthy elements ndarray
var odtypes = dtypes( 'boolean_and_generic' );
var policies = {
	'output': 'boolean_and_generic',
	'casting': 'none'
};
var table = {
	'types': [
		'float64', 'bool', // input, output
		'float32', 'bool'  // input, output

		// FIXME: add specialized support for `ccusome` and `zcusome` once the corresponding packages are implemented
	],
	'fcns': [
		dcusome,
		scusome
	],
	'default': gcusome
};
var options = {
	'strictTraversalOrder': true
};


// MAIN //

/**
* Cumulatively tests whether at least `k` elements along one or more ndarray dimensions are truthy.
*
* @private
* @name cusome
* @type {Function}
* @param {ndarray} x - input ndarray
* @param {ndarray} k - ndarray containing the minimum number of truthy elements
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @param {*} [options.dtype] - output ndarray data type
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* var Float64Array = require( '@stdlib/array-float64' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var ndarray = require( '@stdlib/ndarray-ctor' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 0.0, 1.0, 0.0, 4.0, 3.0, 0.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 3, 1, 2 ];
*
* // Define the array strides:
* var sx = [ 2, 2, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create an ndarray containing the minimum number of truthy elements:
* var k = scalar2ndarray( 2, {
*     'dtype': 'int32'
* });
*
* // Perform operation:
* var out = cusome( x, k );
* // returns <ndarray>[ [ [ false, false ] ], [ [ false, true ] ], [ [ true, true ] ] ]
*/
var cusome = factory( table, [ idtypes0, idtypes1 ], odtypes, policies, options ); // eslint-disable-line max-len


// EXPORTS //

module.exports = cusome;

// exports: { "assign": "cusome.assign" }
